func diameterOfBinaryTree(root *TreeNode) int {
	ans := 1
	var depth func(root *TreeNode) int
	depth = func(root *TreeNode) int {
		if root == nil {
			return 0
		}
		L := depth(root.Left)
		R := depth(root.Right)
		if L+R+1 > ans {
			ans = L + R + 1
		}
		if L > R {
			return L + 1
		}
		return R + 1
	}
	depth(root)
	return ans - 1
}

