func diameterOfBinaryTree(root *TreeNode) int {
	ans := 1
	var depth func(node *TreeNode) int
	depth = func(node *TreeNode) int {
		// 访问到空节点了，返回 0
		if node == nil {
			return 0
		}
		// 左儿子为根的子树的深度
		L := depth(node.Left)
		// 右儿子为根的子树的深度
		R := depth(node.Right)
		// 计算 dNode 即 L+R+1 并更新 ans
		if L+R+1 > ans {
			ans = L + R + 1
		}
		// 返回该节点为根的子树的深度
		if L > R {
			return L + 1
		}
		return R + 1
	}
	depth(root)
	return ans - 1
}
